// Validate IoT sensor data
function Filter(msg, metadata, msgType) {
  try {
    // Parse JSON data
    var data = JSON.parse(msg);

    // Validate required fields
    if (!data.deviceId || !data.timestamp || !data.temperature || !data.humidity) {
      return false;
    }

    // Validate data types and ranges
    if (typeof data.deviceId !== 'string' || data.deviceId.length === 0) {
      return false;
    }

    if (typeof data.temperature !== 'number' || data.temperature < -50 || data.temperature > 100) {
      return false;
    }

    if (typeof data.humidity !== 'number' || data.humidity < 0 || data.humidity > 100) {
      return false;
    }

    // Validate timestamp
    var timestamp = new Date(data.timestamp);
    if (isNaN(timestamp.getTime())) {
      return false;
    }

    // Set metadata for downstream processing
    metadata.deviceId = data.deviceId;
    metadata.timestamp = data.timestamp;
    metadata.temperature = data.temperature;
    metadata.humidity = data.humidity;
    metadata.pressure = data.pressure || null;

    return true;
  } catch (e) {
    return false;
  }
}

// Transform and enrich IoT sensor data
function Transform(msg, metadata, msgType) {
  try {
    var data = JSON.parse(msg);

    // Convert temperature to Fahrenheit if needed
    var tempF = (data.temperature * 9/5) + 32;

    // Calculate heat index if both temperature and humidity are available
    var heatIndex = null;
    if (data.temperature >= 26.7 && data.humidity >= 40) {
      // Simplified heat index calculation
      heatIndex = data.temperature + (0.5 * data.humidity);
    }

    // Determine alert level based on thresholds
    var alertLevel = 'normal';
    if (data.temperature > 45 || data.humidity > 90) {
      alertLevel = 'critical';
    } else if (data.temperature > 35 || data.humidity > 80) {
      alertLevel = 'warning';
    }

    // Create enriched data object
    var enrichedData = {
      deviceId: data.deviceId,
      timestamp: data.timestamp,
      temperature: data.temperature,
      temperatureF: tempF,
      humidity: data.humidity,
      pressure: data.pressure,
      heatIndex: heatIndex,
      alertLevel: alertLevel,
      processedAt: new Date().toISOString(),
      location: metadata.location || 'unknown'
    };

    // Update metadata
    metadata.alertLevel = alertLevel;
    metadata.temperatureF = tempF;
    metadata.heatIndex = heatIndex;
    metadata.processedAt = enrichedData.processedAt;

    return {
      msg: JSON.stringify(enrichedData),
      metadata: metadata,
      msgType: msgType
    };
  } catch (e) {
    throw new Error('Data transformation failed: ' + e.message);
  }
}

// Filter for alert conditions
function Filter(msg, metadata, msgType) {
  return metadata.alertLevel === 'warning' || metadata.alertLevel === 'critical';
}

// Log successful processing
function Log(msg, metadata, msgType) {
  var data = JSON.parse(msg);
  return 'SUCCESS: Processed data for device ' + data.deviceId + ' at ' + data.timestamp + ' with alert level: ' + data.alertLevel;
}

// Log processing errors
function Log(msg, metadata, msgType) {
  return 'ERROR: Failed to process message - ' + msg + ' | Error: ' + (metadata.error || 'Unknown error');
}
